const input = $input.first().json;
    const toEmail = input.to_email || input.email || "arusamy71053@gmail.com";
    const recipientName = input.user_name || input.name || "Wealthyo Household Owner";
    const isTest = Boolean(input.is_test);
    const alertItems = Array.isArray(input.alerts) ? input.alerts : [];
    const subject = isTest ? "[TEST EMAIL] Wealthyo Executive Alert Digest" : "Wealthyo Monthly Household Financial Alert
  Digest";

    let alertRowsHtml = "";
    if (alertItems.length > 0) {
      alertRowsHtml = alertItems.map(item => "<tr style='border-bottom: 1px solid rgba(255,255,255,0.1);'><td style='padding:
  12px; color: #ffd700; font-weight: 700;'>" + (item.alertName || item.title || "Alert Rule") + "</td><td style='padding: 12px;
  color: #cbd5e1;'>" + (item.targetModule || item.module || "Overview") + "</td><td style='padding: 12px; color: #00ff88; font-
  weight: 700;'>" + (item.referenceValue || item.dueDate || "1st of Month") + "</td><td style='padding: 12px; color: #94a3b8;
  '>" + (item.frequency || "Monthly") + "</td></tr>").join("");
    } else {
      alertRowsHtml = "<tr style='border-bottom: 1px solid rgba(255,255,255,0.1);'><td style='padding: 12px; color: #ffd700;
  font-weight: 700;'>Monthly balance sheet digest</td><td style='padding: 12px; color: #cbd5e1;'>Overview</td><td
  style='padding: 12px; color: #00ff88; font-weight: 700;'>Every month end</td><td style='padding: 12px; color: #94a3b8;
  '>Monthly</td></tr>";
    }

    const htmlBody = "<html><body style='background-color:#060a12;color:#f4efe4;font-family:sans-serif;padding:24px;'><div
  style='max-width:620px;margin:0 auto;background:#0f172a;border:2px solid #c9a84c;border-radius:24px;padding:32px;'><div
  style='text-align:center;border-bottom:1px solid rgba(201,168,76,0.3);padding-bottom:20px;margin-bottom:24px;'><span
  style='background:rgba(0,255,136,0.16);color:#00ff88;border:1px solid rgba(0,255,136,0.4);padding:4px 12px;border-
  radius:99px;font-size:11px;font-weight:800;letter-spacing:0.1em;'>" + (isTest ? "TEST RUN SIMULATION" : "WEALTHYO PREMIUM
  ALERTS") + "</span><h1 style='color:#ffd700;font-size:26px;margin:10px 0 4px;'>Executive Financial Alert Digest</h1><p
  style='color:#cbd5e1;font-size:13px;margin:0;'>Automated Household Wealth Engine</p></div><p style='font-size:14px;'>Hello
  <strong>" + recipientName + "</strong>,</p><p style='font-size:13px;color:#cbd5e1;line-height:1.6;'>Here is your configured
  financial alert pulse. All active rules scheduled for execution are itemized below:</p><table style='width:100%;border-
  collapse:collapse;margin:20px 0;font-size:13px;text-align:left;'><thead><tr style='background:rgba(255,255,255,0.06);
  color:#94a3b8;'><th style='padding:10px;'>Alert Rule</th><th style='padding:10px;'>Module</th><th style='padding:10px;
  '>Trigger / Due</th><th style='padding:10px;'>Frequency</th></tr></thead><tbody>" + alertRowsHtml + "</tbody></table><div
  style='text-align:center;margin-top:24px;'><a href='https://wealthyo.web.app/dashboard' style='background:linear-
  gradient(135deg,#ffd700,#f59e0b);color:#060a12;font-weight:900;text-decoration:none;padding:12px 28px;border-radius:14px;
  display:inline-block;font-size:13px;'>Open Wealthyo Dashboard ↗</a></div><div style='text-align:center;margin-top:30px;font-
  size:11px;color:#64748b;border-top:1px solid rgba(255,255,255,0.08);padding-top:16px;'>Sent via Wealthyo Household Engine.
  <br>Automated Wealth Management &amp; Asset Protection.</div></div></body></html>";

    return [{
      json: {
        from: "Wealthyo Alerts <alerts@wealthyo.in>",
        to: toEmail,
        subject: subject,
        html: htmlBody
      }
    }];
